// GENERATED from the Stitch "Helix avatar" catalog (zip 9). Do not hand-edit; regenerate instead.
// Changes vs Stitch: palette -> placeholders, unique id prefix, prefixed keyframes, reduced-motion block,
// and the gradients/filters live INSIDE each svg (Stitch put them in a display:none svg, which erases the cloud).
export const AVATAR_CSS = ".helix-avatar {\n      transform-origin: center center;\n      transition: filter 0.4s ease;\n    }\n\n    /* Visor & Base Glow */\n    .helix-avatar .visor-ring {\n      transition: stroke 0.35s ease, filter 0.35s ease;\n    }\n    .helix-avatar .ambient-glow {\n      transition: fill 0.35s ease, opacity 0.35s ease;\n    }\n\n    /* Default visibility of badges and eyes */\n    .helix-avatar .pill-eyes {\n      display: block;\n      transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);\n      transform-origin: 160px 145px;\n    }\n    .helix-avatar .happy-eyes,\n    .helix-avatar .error-eyes {\n      display: none;\n      opacity: 0;\n    }\n    .helix-avatar .badge-unsure,\n    .helix-avatar .badge-done,\n    .helix-avatar .badge-error {\n      display: none;\n      opacity: 0;\n      transition: opacity 0.3s ease;\n    }\n\n    .helix-avatar .dna-helix {\n      transform-origin: 160px 222px;\n    }\n\n    /* 1. STATE: IDLE (Reposo) */\n    .helix-avatar.is-idle .body-group {\n      animation: hxav-floatBreath 4.5s ease-in-out infinite;\n      transform-origin: 160px 150px;\n    }\n    .helix-avatar.is-idle .pill-eyes {\n      display: block !important;\n      animation: hxav-naturalBlink 5.5s infinite;\n    }\n    .helix-avatar.is-idle .dna-helix {\n      animation: hxav-helixGentleSpin 3.2s ease-in-out infinite;\n    }\n\n    /* 2. STATE: THINKING (Procesando) */\n    .helix-avatar.is-thinking .body-group {\n      animation: hxav-thinkMicroHover 2s ease-in-out infinite;\n      transform-origin: 160px 150px;\n    }\n    .helix-avatar.is-thinking .pill-eyes {\n      display: block !important;\n      transform: translateY(-7px) scale(0.88);\n      animation: none !important;\n    }\n    .helix-avatar.is-thinking .dna-helix {\n      animation: hxav-fastHelixSpin 0.8s ease-in-out infinite alternate;\n    }\n\n    /* 3. STATE: SPEAKING (Emitiendo Voz) */\n    .helix-avatar.is-speaking .body-group {\n      animation: hxav-floatBreath 3.8s ease-in-out infinite;\n      transform-origin: 160px 150px;\n    }\n    .helix-avatar.is-speaking .visor-ring {\n      stroke: #22d3ee !important;\n      filter: drop-shadow(0 0 10px rgba(34, 211, 238, 0.7));\n    }\n    .helix-avatar.is-speaking .eye-left {\n      transform-origin: 140px 145px;\n      animation: hxav-voicePulseLeft 0.25s ease-in-out infinite alternate;\n    }\n    .helix-avatar.is-speaking .eye-right {\n      transform-origin: 180px 145px;\n      animation: hxav-voicePulseRight 0.25s ease-in-out infinite alternate 0.08s;\n    }\n    .helix-avatar.is-speaking .dna-helix {\n      animation: hxav-helixSpeakPulse 0.5s ease-in-out infinite alternate;\n    }\n\n    /* 4. STATE: UNSURE (Duda / Incierto) */\n    .helix-avatar.is-unsure .body-group {\n      animation: hxav-subtleWobble 2.6s ease-in-out infinite;\n      transform-origin: 160px 150px;\n    }\n    .helix-avatar.is-unsure .ambient-glow {\n      fill: #f59e0b;\n      opacity: 0.18;\n    }\n    .helix-avatar.is-unsure .visor-ring {\n      stroke: #f59e0b !important;\n      filter: drop-shadow(0 0 12px rgba(245, 158, 11, 0.75));\n    }\n    .helix-avatar.is-unsure .eye-left {\n      transform-origin: 140px 145px;\n      transform: rotate(13deg);\n      filter: drop-shadow(0 0 6px rgba(251, 191, 36, 0.9));\n    }\n    .helix-avatar.is-unsure .eye-right {\n      transform-origin: 180px 145px;\n      transform: rotate(-13deg);\n      filter: drop-shadow(0 0 6px rgba(251, 191, 36, 0.9));\n    }\n    .helix-avatar.is-unsure .badge-unsure {\n      display: block !important;\n      opacity: 1 !important;\n      animation: hxav-badgeFloat 2.6s ease-in-out infinite;\n    }\n\n    /* 5. STATE: DONE (Completado / Éxito) */\n    .helix-avatar.is-done .body-group {\n      animation: hxav-happyBounce 2.8s ease-in-out infinite;\n      transform-origin: 160px 150px;\n    }\n    .helix-avatar.is-done .ambient-glow {\n      fill: #10b981;\n      opacity: 0.22;\n    }\n    .helix-avatar.is-done .visor-ring {\n      stroke: #10b981 !important;\n      filter: drop-shadow(0 0 14px rgba(16, 185, 129, 0.75));\n    }\n    .helix-avatar.is-done .pill-eyes {\n      display: none !important;\n    }\n    .helix-avatar.is-done .happy-eyes {\n      display: block !important;\n      opacity: 1 !important;\n    }\n    .helix-avatar.is-done .badge-done {\n      display: block !important;\n      opacity: 1 !important;\n      animation: hxav-badgeFloat 2.8s ease-in-out infinite;\n    }\n    .helix-avatar.is-done .dna-helix {\n      animation: hxav-helixGentleSpin 2s ease-in-out infinite;\n    }\n\n    /* 6. STATE: ERROR (Fallo / Bloqueo) */\n    .helix-avatar.is-error {\n      filter: grayscale(0.5) opacity(0.88);\n    }\n    .helix-avatar.is-error * {\n      animation: none !important;\n    }\n    .helix-avatar.is-error .ambient-glow {\n      fill: #ef4444;\n      opacity: 0.18;\n    }\n    .helix-avatar.is-error .visor-ring {\n      stroke: #ef4444 !important;\n      filter: drop-shadow(0 0 14px rgba(239, 68, 68, 0.85));\n    }\n    .helix-avatar.is-error .pill-eyes {\n      display: none !important;\n    }\n    .helix-avatar.is-error .error-eyes {\n      display: block !important;\n      opacity: 1 !important;\n    }\n    .helix-avatar.is-error .badge-error {\n      display: block !important;\n      opacity: 1 !important;\n    }\n\n    /* Keyframe Animations */\n    @keyframes hxav-floatBreath {\n      0%, 100% { transform: translateY(0px) scale(1); }\n      50% { transform: translateY(-5px) scale(1.02); }\n    }\n    @keyframes hxav-naturalBlink {\n      0%, 94%, 98%, 100% { transform: scaleY(1); }\n      96% { transform: scaleY(0.08); }\n    }\n    @keyframes hxav-fastHelixSpin {\n      0% { transform: scaleX(0.2) rotate(-6deg); opacity: 0.6; }\n      100% { transform: scaleX(1) rotate(6deg); opacity: 1; }\n    }\n    @keyframes hxav-thinkMicroHover {\n      0%, 100% { transform: translateY(0px) rotate(0deg); }\n      50% { transform: translateY(-4px) rotate(0.8deg); }\n    }\n    @keyframes hxav-voicePulseLeft {\n      0% { transform: scaleY(0.85); }\n      100% { transform: scaleY(1.15); }\n    }\n    @keyframes hxav-voicePulseRight {\n      0% { transform: scaleY(1.15); }\n      100% { transform: scaleY(0.85); }\n    }\n    @keyframes hxav-helixSpeakPulse {\n      0% { transform: scale(0.9); opacity: 0.75; }\n      100% { transform: scale(1.15); opacity: 1; }\n    }\n    @keyframes hxav-subtleWobble {\n      0%, 100% { transform: rotate(0deg); }\n      25% { transform: rotate(-2.5deg); }\n      75% { transform: rotate(2.5deg); }\n    }\n    @keyframes hxav-happyBounce {\n      0%, 100% { transform: translateY(0); }\n      50% { transform: translateY(-4px) scale(1.01); }\n    }\n    @keyframes hxav-badgeFloat {\n      0%, 100% { transform: translateY(0); }\n      50% { transform: translateY(-3px); }\n    }\n    @keyframes hxav-helixGentleSpin {\n      0%, 100% { transform: scaleX(0.7); }\n      50% { transform: scaleX(1); }\n    }\n/* the state halo is wider than the viewBox: do not clip it into a square */\n.helix-avatar { overflow: visible; }\n\n/* Compact (< 64px): the thought bubbles, eye tilt and voice pulse are too small to read at chat sizes,\n   so exaggerate them. Everything here only applies with .is-compact. */\n.helix-avatar.is-compact .badge-unsure,\n.helix-avatar.is-compact .badge-done,\n.helix-avatar.is-compact .badge-error { transform-origin: 242px 70px; transform: scale(2.7); }\n.helix-avatar.is-compact.is-unsure .badge-unsure { animation: hxav-badgeFloatC 2.6s ease-in-out infinite; }\n.helix-avatar.is-compact.is-done .badge-done { animation: hxav-badgeFloatC 2.8s ease-in-out infinite; }\n@keyframes hxav-badgeFloatC { 0%, 100% { transform: scale(2.7) translateY(0); } 50% { transform: scale(2.7) translateY(-2px); } }\n.helix-avatar.is-compact .visor-ring { stroke-width: 6; }\n.helix-avatar.is-compact.is-unsure .eye-left { transform: rotate(28deg); }\n.helix-avatar.is-compact.is-unsure .eye-right { transform: rotate(-28deg); }\n.helix-avatar.is-compact.is-unsure .ambient-glow,\n.helix-avatar.is-compact.is-done .ambient-glow,\n.helix-avatar.is-compact.is-error .ambient-glow { opacity: 0.6; transform-origin: 160px 150px; transform: scale(1.4); }\n.helix-avatar.is-compact.is-speaking .ambient-glow { fill: #22d3ee; transform-origin: 160px 150px; animation: hxav-speakGlow 0.55s ease-in-out infinite alternate; }\n@keyframes hxav-speakGlow { 0% { opacity: 0.2; transform: scale(1); } 100% { opacity: 0.8; transform: scale(1.5); } }\n.helix-avatar.is-compact.is-speaking .eye-left { animation: hxav-voiceBigL 0.25s ease-in-out infinite alternate; }\n.helix-avatar.is-compact.is-speaking .eye-right { animation: hxav-voiceBigR 0.25s ease-in-out infinite alternate 0.08s; }\n@keyframes hxav-voiceBigL { 0% { transform: scaleY(0.6); } 100% { transform: scaleY(1.25); } }\n@keyframes hxav-voiceBigR { 0% { transform: scaleY(1.25); } 100% { transform: scaleY(0.6); } }\n\n/* older chat messages keep a calm, still avatar */\n.helix-avatar.is-static, .helix-avatar.is-static * { animation: none !important; }\n\n@media (prefers-reduced-motion: reduce) {\n  .helix-avatar, .helix-avatar * { animation: none !important; }\n}\n";

